mapper.select:
SELECT

FROM performance
WHERE id = #{id}
AND publisher_id = #{publisherId}
FOR UPDATE

mapper.update:
UPDATE performance
SET description = #{description},
    cover_url   = #{coverUrl},
    updated_at  = #{updatedAt}
WHERE id = #{id}
  AND publisher_id = #{publisherId}
  AND status IN (1, 2) /* 1 = PUBLISHED, 2 = WITHDRAWN */

UPDATE performance
SET status       = 1,
    published_at = #{publishedAt},
    updated_at   = #{publishedAt}
WHERE id = #{id}
  AND publisher_id = #{publisherId}
  AND status = 0 /* 0 = DRAFT，只有草稿可以发布 */

UPDATE performance
SET status     = 2,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND publisher_id = #{publisherId}
  AND status = 1 /* 1 = PUBLISHED，只有已发布可以下架 */

